$ErrorActionPreference='Stop';Set-StrictMode -Version Latest
function Assert([bool]$c,[string]$m){if(-not$c){throw $m}}
function Wait-File([string]$p){$d=[DateTime]::UtcNow.AddSeconds(20);while([DateTime]::UtcNow-lt$d){if(Test-Path -LiteralPath $p -PathType Leaf){return};Start-Sleep -Milliseconds 150};throw "Timed out: $p"}
function Stop-P($p){if($p){try{if(-not$p.HasExited){Stop-Process -Id $p.Id -Force -ErrorAction SilentlyContinue;$p.WaitForExit(5000)|Out-Null}}catch{}}}
function New-Root([string]$n){$p=Join-Path $env:RUNNER_TEMP ('sokna-p2b-'+$n+'-'+[guid]::NewGuid().ToString('N'));New-Item -ItemType Directory -Path $p -Force|Out-Null;$p}
function Fixture([string]$r,[int64]$seq,[string]$id){$o=@(& $FixtureExe --root $r --variant valid --sequence ([string]$seq) --release-id $id 2>&1);if($LASTEXITCODE-ne0){throw($o-join"`n")};($o-join"`n")|ConvertFrom-Json}
function Signed([string]$method,[string]$url,[string]$keyPath,[string]$keyId,[byte[]]$body,[string]$idem=''){
  $u=[Uri]$url;$key=[Convert]::FromBase64String((Get-Content $keyPath -Raw).Trim());$ts=[DateTimeOffset]::UtcNow.ToString('O',[Globalization.CultureInfo]::InvariantCulture);$nonce=[guid]::NewGuid().ToString('N');$bh=[Convert]::ToHexString([Security.Cryptography.SHA256]::HashData($body)).ToLowerInvariant();$canon="$($method.ToUpperInvariant())`n$($u.PathAndQuery)`n1.0`n$ts`n$nonce`n$bh";$h=[Security.Cryptography.HMACSHA256]::new($key);try{$sig=[Convert]::ToHexString($h.ComputeHash([Text.Encoding]::UTF8.GetBytes($canon))).ToLowerInvariant()}finally{$h.Dispose()};$headers=@{'X-Sokna-Maintenance-Protocol'='1.0';'X-Sokna-Timestamp'=$ts;'X-Sokna-Nonce'=$nonce;'X-Sokna-Key-Id'=$keyId;'X-Sokna-Body-SHA256'=$bh;'X-Sokna-Signature'=$sig};if($idem){$headers['X-Sokna-Idempotency-Key']=$idem};$a=@{Uri=$url;Method=$method;Headers=$headers;SkipHttpErrorCheck=$true;TimeoutSec=30};if($body.Length){$a.Body=$body;$a.ContentType='application/json; charset=utf-8'};Invoke-WebRequest @a
}
function New-Apache([string]$r){
  Assert ($null-eq(Get-Service SoknaApache -ErrorAction SilentlyContinue)) 'SoknaApache already exists on runner.';$d=Join-Path $r 'fake\Apache24\bin';New-Item -ItemType Directory -Path $d -Force|Out-Null;$exe=Join-Path $d 'httpd.exe';Copy-Item "$env:SystemRoot\System32\cmd.exe" $exe;$bin='"'+$exe+'" -k runservice';$o=@(& sc.exe create SoknaApache 'binPath=' $bin 'start=' demand 'obj=' 'NT AUTHORITY\LocalService' 2>&1);Assert ($LASTEXITCODE-eq0) "sc create failed: $($o-join' | ')"
}
function Del-Apache(){if(Get-Service SoknaApache -ErrorAction SilentlyContinue){& sc.exe delete SoknaApache|Out-Null;for($i=0;$i-lt40;$i++){if(-not(Get-Service SoknaApache -ErrorAction SilentlyContinue)){break};Start-Sleep -Milliseconds 250}}}
function Assert-Acl([string]$web,[string]$recovery){$w=@((Get-Acl $web).Access|? AccessControlType -eq Allow|%{$_.IdentityReference.Translate([Security.Principal.SecurityIdentifier]).Value});$r=@((Get-Acl $recovery).Access|? AccessControlType -eq Allow|%{$_.IdentityReference.Translate([Security.Principal.SecurityIdentifier]).Value});Assert ($w-contains'S-1-5-19') 'LocalService missing from web key ACL.';Assert (-not($r-contains'S-1-5-19')) 'LocalService must not read recovery key.';foreach($b in @('S-1-1-0','S-1-5-11','S-1-5-32-545','S-1-5-32-546')){Assert(-not($w-contains$b))"Broad SID $b on web key";Assert(-not($r-contains$b))"Broad SID $b on recovery key"}}
$SupervisorExe=(Resolve-Path $SupervisorExe).Path;$FixtureExe=(Resolve-Path $FixtureExe).Path
$root=New-Root main;$f=Fixture $root 101 release-p2b-101;$inbox=Join-Path $root 'update\inbox';New-Item -ItemType Directory -Path $inbox -Force|Out-Null;$pkg=[IO.Path]::GetFileName([string]$f.package);Copy-Item $f.package (Join-Path $inbox $pkg);Copy-Item $f.identity (Join-Path $root 'installed-release-identity.json');New-Apache $root;$p=$null
try{
  $p=Start-Process $SupervisorExe -ArgumentList @('--data-root',$root,'--port','17631') -PassThru -WindowStyle Hidden;Wait-File (Join-Path $root 'control-plane.json');Wait-File (Join-Path $root 'web-adapter-acl.json');$ev=Get-Content (Join-Path $root 'web-adapter-acl.json') -Raw|ConvertFrom-Json;Assert([string]$ev.state-eq'ready')"ACL not ready: $($ev|ConvertTo-Json -Compress)";Assert([string]$ev.service_sid-eq'S-1-5-19')'Service SID mismatch';Assert-Acl (Join-Path $root 'secrets\web-adapter.key') (Join-Path $root 'secrets\recovery-console.key');$base='http://127.0.0.1:17631/';$wk=Join-Path $root 'secrets\web-adapter.key';$rk=Join-Path $root 'secrets\recovery-console.key';$body=[Text.Json.JsonSerializer]::SerializeToUtf8Bytes([ordered]@{package_ref=$pkg;operator_id='user:test-operator'});$resp=Signed POST ($base+'v1/update/stage') $wk web-adapter $body idem-p2b-001;Assert([int]$resp.StatusCode-eq200)"stage failed: $($resp.Content)";$j=$resp.Content|ConvertFrom-Json;Assert([string]$j.state-eq'staged')'not staged';$op=[string]$j.operation_id;Assert(-not[bool]$j.data.operation.activation_performed)'activation occurred';Assert(-not[bool]$j.data.operation.database_mutation_performed)'DB mutation occurred';$again=Signed POST ($base+'v1/update/stage') $wk web-adapter $body idem-p2b-001;$aj=$again.Content|ConvertFrom-Json;Assert([string]$aj.operation_id-eq$op)'idempotency changed op';Assert([bool]$aj.data.reconciled)'not reconciled';$different=[Text.Json.JsonSerializer]::SerializeToUtf8Bytes([ordered]@{package_ref=$pkg;operator_id='user:different'});$c=Signed POST ($base+'v1/update/stage') $wk web-adapter $different idem-p2b-001;Assert([int]$c.StatusCode-eq409)'idempotency conflict not 409';$q=Signed GET ($base+'v1/operations/'+$op) $rk recovery-console ([byte[]]::new(0));Assert([int]$q.StatusCode-eq200)'operation lookup failed';$forbidden=Signed POST ($base+'v1/update/stage') $rk recovery-console $body idem-recovery;Assert([int]$forbidden.StatusCode-eq403)'recovery key authorized mutation';$unsafe=[Text.Json.JsonSerializer]::SerializeToUtf8Bytes([ordered]@{package_ref='..\x.zip';operator_id='user:test'});$u=Signed POST ($base+'v1/update/stage') $wk web-adapter $unsafe idem-unsafe;Assert([int]$u.StatusCode-eq400)'unsafe package ref accepted';$record=Get-Content (Join-Path $root ('operations\op-'+$op+'.json')) -Raw|ConvertFrom-Json;Assert([string]$record.operator_id-eq'user:test-operator')'operator missing from durable op'
}finally{Stop-P $p;Del-Apache}
New-Apache $root;$p=$null
try{$p=Start-Process $SupervisorExe -ArgumentList @('--data-root',$root,'--port','17631') -PassThru -WindowStyle Hidden;Wait-File(Join-Path $root 'control-plane.json');$q=Signed GET ('http://127.0.0.1:17631/v1/operations/'+$op) (Join-Path $root 'secrets\recovery-console.key') recovery-console ([byte[]]::new(0));Assert([string](($q.Content|ConvertFrom-Json).data.state)-eq'staged')'restart lost operation'}finally{Stop-P $p;Del-Apache}
$pending=New-Root pending;$pf=Fixture $pending 102 release-p2b-102;$pi=Join-Path $pending 'update\inbox';New-Item -ItemType Directory -Path $pi -Force|Out-Null;$pp=[IO.Path]::GetFileName([string]$pf.package);Copy-Item $pf.package (Join-Path $pi $pp);Copy-Item $pf.identity (Join-Path $pending 'installed-release-identity.json');$p=$null
try{$p=Start-Process $SupervisorExe -ArgumentList @('--data-root',$pending,'--port','17632') -PassThru -WindowStyle Hidden;Wait-File(Join-Path $pending 'control-plane.json');Wait-File(Join-Path $pending 'web-adapter-acl.json');$ev=Get-Content (Join-Path $pending 'web-adapter-acl.json') -Raw|ConvertFrom-Json;Assert([string]$ev.state-eq'acl_pending')'missing Apache did not remain pending';$b=[Text.Json.JsonSerializer]::SerializeToUtf8Bytes([ordered]@{package_ref=$pp;operator_id='user:test'});$r=Signed POST 'http://127.0.0.1:17632/v1/update/stage' (Join-Path $pending 'secrets\web-adapter.key') web-adapter $b idem-pending;Assert([int]$r.StatusCode-eq503)'ACL pending did not fail closed';Assert(-not(Test-Path(Join-Path $pending 'update\release-sequence.json')))'ACL pending reached engine'}finally{Stop-P $p}
